#!/usr/bin/env python3
"""Self-contained evidence replay implementation (stdlib only)."""
import sys
import json
import re
import heapq

MAX_INPUT = 2097152
LABEL_RE = re.compile(r'^[a-z0-9]{1,8}$')

PRI_RELEASE = 1
PRI_PING = 2
PRI_ACK = 3
PRI_TIMEOUT = 4
PRI_HOSTACK = 5


class Invalid(Exception):
    pass


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _pairs_hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid("duplicate key")
        d[k] = v
    return d


def _reject_const(x):
    raise Invalid("bad constant")


def parse_input(raw):
    if len(raw) > MAX_INPUT:
        raise Invalid("too big")
    try:
        text = raw.decode('utf-8')
    except Exception:
        raise Invalid("bad utf8")
    try:
        obj = json.loads(text, object_pairs_hook=_pairs_hook,
                         parse_constant=_reject_const)
    except Invalid:
        raise
    except Exception:
        raise Invalid("bad json")
    return obj


def validate(obj):
    if not isinstance(obj, dict):
        raise Invalid("root not object")
    if set(obj.keys()) != {"version", "n", "capacity", "edges", "rounds"}:
        raise Invalid("root keys")
    if not _is_int(obj["version"]) or obj["version"] != 1:
        raise Invalid("version")
    n = obj["n"]
    if not _is_int(n) or n < 2 or n > 96:
        raise Invalid("n")
    cap = obj["capacity"]
    if not isinstance(cap, list) or len(cap) != n:
        raise Invalid("capacity")
    for c in cap:
        if not _is_int(c) or c < 0 or c > 48:
            raise Invalid("capacity val")
    edges_in = obj["edges"]
    if not isinstance(edges_in, list) or len(edges_in) > 384:
        raise Invalid("edges")
    edges = []
    seen_uv = set()
    for eo in edges_in:
        if not isinstance(eo, dict):
            raise Invalid("edge obj")
        if set(eo.keys()) != {"u", "v", "ping_us", "ack_us", "label"}:
            raise Invalid("edge keys")
        u = eo["u"]
        v = eo["v"]
        pu = eo["ping_us"]
        au = eo["ack_us"]
        lb = eo["label"]
        if not _is_int(u) or not _is_int(v):
            raise Invalid("edge u/v type")
        if not (0 <= u < v < n):
            raise Invalid("edge u/v range")
        if (u, v) in seen_uv:
            raise Invalid("dup edge")
        seen_uv.add((u, v))
        if not _is_int(pu) or pu < 1 or pu > 10000:
            raise Invalid("ping_us")
        if not _is_int(au) or au < 1 or au > 10000:
            raise Invalid("ack_us")
        if not isinstance(lb, str) or not LABEL_RE.match(lb):
            raise Invalid("label")
        edges.append({"u": u, "v": v, "ping_us": pu, "ack_us": au, "label": lb})
    rounds_in = obj["rounds"]
    if not isinstance(rounds_in, list) or len(rounds_in) > 48:
        raise Invalid("rounds")
    E = len(edges)
    rounds = []
    for ro in rounds_in:
        if not isinstance(ro, dict):
            raise Invalid("round obj")
        if set(ro.keys()) != {"launch_us", "timeout_us", "host_delay_us",
                              "drop_host_ack", "drop_ping", "drop_ack"}:
            raise Invalid("round keys")
        la = ro["launch_us"]
        to = ro["timeout_us"]
        hd = ro["host_delay_us"]
        dha = ro["drop_host_ack"]
        dp = ro["drop_ping"]
        da = ro["drop_ack"]
        if not _is_int(la) or la < 0 or la > 1000000000:
            raise Invalid("launch_us")
        if not _is_int(to) or to < 1 or to > 1000000:
            raise Invalid("timeout_us")
        if not _is_int(hd) or hd < 1 or hd > 10000:
            raise Invalid("host_delay_us")
        if not isinstance(dha, bool):
            raise Invalid("drop_host_ack")
        if not isinstance(dp, list) or not isinstance(da, list):
            raise Invalid("drop lists")
        dps = set()
        for x in dp:
            if not _is_int(x) or x < 0 or x >= E:
                raise Invalid("drop_ping id")
            if x in dps:
                raise Invalid("drop_ping dup")
            dps.add(x)
        das = set()
        for x in da:
            if not _is_int(x) or x < 0 or x >= E:
                raise Invalid("drop_ack id")
            if x in das:
                raise Invalid("drop_ack dup")
            das.add(x)
        rounds.append({"launch_us": la, "timeout_us": to, "host_delay_us": hd,
                       "drop_host_ack": dha, "drop_ping": dps, "drop_ack": das})
    return n, cap, edges, rounds


class Entry:
    __slots__ = ("round", "node", "proof", "finalized", "complete",
                 "out_edges", "expected", "credited", "wait_parents",
                 "cached_proof", "cached_complete")

    def __init__(self, r, node, out_edges):
        self.round = r
        self.node = node
        self.proof = set()
        self.finalized = False
        self.complete = None
        self.out_edges = out_edges
        self.expected = len(out_edges)
        self.credited = {}
        self.wait_parents = set()
        self.cached_proof = frozenset()
        self.cached_complete = False


def replay(n, cap, edges, rounds):
    E = len(edges)
    eu = [0] * E
    ev = [0] * E
    eping = [0] * E
    eack = [0] * E
    elabel = [""] * E
    for i, e in enumerate(edges):
        eu[i] = e["u"]
        ev[i] = e["v"]
        eping[i] = e["ping_us"]
        eack[i] = e["ack_us"]
        elabel[i] = e["label"]
    adj = [[] for _ in range(n)]
    for i in range(E):
        adj[eu[i]].append(i)

    R = len(rounds)
    launch = [0] * R
    deadline = [0] * R
    hostdelay = [0] * R
    dhostack = [False] * R
    dpping = [None] * R
    dpack = [None] * R
    for r, ro in enumerate(rounds):
        launch[r] = ro["launch_us"]
        deadline[r] = ro["launch_us"] + ro["timeout_us"]
        hostdelay[r] = ro["host_delay_us"]
        dhostack[r] = ro["drop_host_ack"]
        dpping[r] = ro["drop_ping"]
        dpack[r] = ro["drop_ack"]

    source = 0
    dest = n - 1

    # metrics
    network_ping_tx = 0
    network_ack_tx = 0
    host_ack_tx = 0
    dedup_ping = 0
    capacity_drops = 0
    late_ping = 0
    ignored_ack = 0
    allocations = 0

    node_count = [0] * n
    cache_peak = [0] * n
    peak_entries = 0
    total_entries = 0

    entries = {}

    # per round outputs
    source_started = [False] * R
    source_final_us = [None] * R
    source_complete = [None] * R
    host_delivery_us = [None] * R
    source_proof = [None] * R

    heap = []
    seq = 0

    def push(time, pri, r, key, etype, payload):
        nonlocal seq
        heapq.heappush(heap, (time, pri, r, key, seq, etype, payload))
        seq += 1

    def transmit_ack(edge_id, proof, comp, t, r):
        nonlocal network_ack_tx
        network_ack_tx += 1
        if edge_id not in dpack[r]:
            push(t + eack[edge_id], PRI_ACK, r, edge_id, 'ack',
                 (edge_id, proof, comp))

    def finalize(entry, comp, t):
        nonlocal host_ack_tx
        if entry.finalized:
            return
        entry.finalized = True
        entry.complete = comp
        entry.cached_proof = frozenset(entry.proof)
        entry.cached_complete = comp
        r = entry.round
        node = entry.node
        # transmit ACK to waiting parents
        if entry.wait_parents:
            for pe in entry.wait_parents:
                transmit_ack(pe, entry.cached_proof, comp, t, r)
        if node == source:
            source_final_us[r] = t
            source_complete[r] = comp
            source_proof[r] = entry.cached_proof
            host_ack_tx += 1
            if not dhostack[r]:
                push(t + hostdelay[r], PRI_HOSTACK, r, -1, 'hostack', None)

    def allocate(r, node, t, parent_edge):
        nonlocal allocations, total_entries, peak_entries, network_ping_tx
        allocations += 1
        out_edges = adj[node]
        entry = Entry(r, node, out_edges)
        entries[(r, node)] = entry
        node_count[node] += 1
        total_entries += 1
        if node_count[node] > cache_peak[node]:
            cache_peak[node] = node_count[node]
        if total_entries > peak_entries:
            peak_entries = total_entries
        if parent_edge is not None:
            entry.wait_parents.add(parent_edge)
        # schedule timeout at deadline
        push(deadline[r], PRI_TIMEOUT, r, node, 'timeout', node)
        # transmit pings
        t_p = t
        for e in out_edges:
            network_ping_tx += 1
            if e not in dpping[r]:
                push(t_p + eping[e], PRI_PING, r, e, 'ping', e)
        if entry.expected == 0:
            finalize(entry, True, t)
        return entry

    # schedule host launches and releases
    for r in range(R):
        push(launch[r], PRI_PING, r, -1, 'hostlaunch', None)
        push(deadline[r] + 1, PRI_RELEASE, r, -1, 'release', None)

    last_time = 0

    while heap:
        t, pri, r, key, sq, etype, payload = heapq.heappop(heap)
        last_time = t
        if etype == 'release':
            # remove all entries for this round
            nonlocal_total = 0
            for node in range(n):
                if (r, node) in entries:
                    del entries[(r, node)]
                    node_count[node] -= 1
                    total_entries -= 1
        elif etype == 'hostlaunch':
            # deliver host ping to source
            entry = entries.get((r, source))
            if entry is not None:
                # shouldn't happen
                pass
            if node_count[source] >= cap[source]:
                capacity_drops += 1
                # not started
            else:
                source_started[r] = True
                allocate(r, source, t, None)
        elif etype == 'ping':
            e = payload
            v = ev[e]
            if t > deadline[r]:
                late_ping += 1
            else:
                entry = entries.get((r, v))
                if entry is not None:
                    dedup_ping += 1
                    entry.wait_parents.add(e)
                    if entry.finalized:
                        transmit_ack(e, entry.cached_proof,
                                     entry.cached_complete, t, r)
                else:
                    if node_count[v] >= cap[v]:
                        capacity_drops += 1
                    else:
                        allocate(r, v, t, e)
        elif etype == 'ack':
            edge_id, proof, comp = payload
            u = eu[edge_id]
            entry = entries.get((r, u))
            if entry is None or entry.finalized or edge_id in entry.credited:
                ignored_ack += 1
            else:
                entry.credited[edge_id] = comp
                entry.proof.add(edge_id)
                entry.proof |= proof
                if len(entry.credited) == entry.expected:
                    cval = all(entry.credited.values())
                    finalize(entry, cval, t)
        elif etype == 'timeout':
            node = payload
            entry = entries.get((r, node))
            if entry is not None and not entry.finalized:
                finalize(entry, False, t)
        elif etype == 'hostack':
            host_delivery_us[r] = t
    # done

    end_us = last_time if R > 0 else 0

    return {
        "R": R, "n": n,
        "source_started": source_started,
        "source_final_us": source_final_us,
        "source_complete": source_complete,
        "host_delivery_us": host_delivery_us,
        "source_proof": source_proof,
        "metrics": {
            "host_probe_tx": R,
            "network_ping_tx": network_ping_tx,
            "network_ack_tx": network_ack_tx,
            "host_ack_tx": host_ack_tx,
            "deduplicated_ping": dedup_ping,
            "capacity_drops": capacity_drops,
            "late_ping": late_ping,
            "ignored_ack": ignored_ack,
            "allocations": allocations,
            "cache_peak": cache_peak,
            "peak_entries": peak_entries,
            "end_us": end_us,
        },
    }


def enumerate_paths(n, edges):
    E = len(edges)
    eu = [e["u"] for e in edges]
    ev = [e["v"] for e in edges]
    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    for i in range(E):
        adj[eu[i]].append(i)
        radj[ev[i]].append(i)
    source = 0
    dest = n - 1
    # forward reach from source
    reach = [False] * n
    stack = [source]
    reach[source] = True
    while stack:
        x = stack.pop()
        for e in adj[x]:
            y = ev[e]
            if not reach[y]:
                reach[y] = True
                stack.append(y)
    # can reach dest (reverse)
    cane = [False] * n
    cane[dest] = True
    stack = [dest]
    while stack:
        x = stack.pop()
        for e in radj[x]:
            y = eu[e]
            if not cane[y]:
                cane[y] = True
                stack.append(y)
    # relevant edges
    rel = [[] for _ in range(n)]
    for i in range(E):
        if reach[eu[i]] and cane[ev[i]]:
            rel[eu[i]].append(i)
    paths = []
    cur = []

    def dfs(x):
        if x == dest:
            paths.append(tuple(cur))
            return
        for e in rel[x]:
            cur.append(e)
            dfs(ev[e])
            cur.pop()

    if reach[source] and cane[source]:
        dfs(source)
    return paths


def build_evidence(n, edges, rounds, rep):
    labels = [e["label"] for e in edges]
    paths = enumerate_paths(n, edges)
    # signature per path
    path_sigs = []
    for p in paths:
        path_sigs.append(tuple(labels[e] for e in p))
    # classes
    sig_paths = {}
    for idx, sig in enumerate(path_sigs):
        sig_paths.setdefault(sig, []).append(idx)
    # precompute edge frozensets
    path_pset = [frozenset(p) for p in paths]

    R = rep["R"]
    evidence = {sig: set() for sig in sig_paths}
    for r in range(R):
        if rep["host_delivery_us"][r] is None:
            continue
        S = rep["source_proof"][r]
        if S is None:
            continue
        S = set(S)
        observed = set()
        for idx in range(len(paths)):
            if path_pset[idx].issubset(S):
                observed.add(path_sigs[idx])
        for sig in observed:
            if sig in evidence:
                evidence[sig].add(r)

    # build classes output
    classes = []
    for sig in sorted(sig_paths.keys()):
        idxs = sig_paths[sig]
        cnt = len(idxs)
        if cnt == 1:
            witnesses = [list(paths[idxs[0]])]
        else:
            witnesses = [list(paths[idxs[0]]), list(paths[idxs[1]])]
        ev = sorted(evidence[sig])
        if not ev:
            state = "unobserved"
        elif cnt == 1:
            state = "unique"
        else:
            state = "ambiguous"
        classes.append({
            "signature": list(sig),
            "candidate_count": cnt,
            "evidence_rounds": ev,
            "state": state,
            "candidate_witnesses": witnesses,
        })

    observable = len(classes)
    observed_classes = sum(1 for c in classes if c["evidence_rounds"])
    unique_obs = sum(1 for c in classes
                     if c["evidence_rounds"] and c["candidate_count"] == 1)
    ambig_obs = sum(1 for c in classes
                    if c["evidence_rounds"] and c["candidate_count"] != 1)
    upper = sum(c["candidate_count"] for c in classes if c["evidence_rounds"])
    if observable == 0:
        cov = "no-routes"
    elif observed_classes == 0:
        cov = "no-evidence"
    elif observed_classes == observable:
        cov = "complete"
    else:
        cov = "partial"

    summary = {
        "topology_paths": len(paths),
        "observable_classes": observable,
        "observed_classes": observed_classes,
        "unique_observed_classes": unique_obs,
        "ambiguous_observed_classes": ambig_obs,
        "path_evidence_lower": observed_classes,
        "path_evidence_upper": upper,
        "coverage_status": cov,
    }
    return classes, summary


def build_output(n, edges, rounds, rep):
    classes, summary = build_evidence(n, edges, rounds, rep)
    R = rep["R"]
    rounds_out = []
    for r in range(R):
        started = rep["source_started"][r]
        sp = rep["source_proof"][r]
        if sp is None:
            sp_list = []
        else:
            sp_list = sorted(sp)
        rounds_out.append({
            "id": r,
            "started": bool(started),
            "source_final_us": rep["source_final_us"][r] if started else None,
            "source_complete": (rep["source_complete"][r]
                                if started else None),
            "host_delivery_us": rep["host_delivery_us"][r],
            "source_proof": sp_list,
        })
    return {
        "rounds": rounds_out,
        "metrics": rep["metrics"],
        "classes": classes,
        "summary": summary,
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        obj = parse_input(raw)
        n, cap, edges, rounds = validate(obj)
    except Invalid:
        sys.stdout.write(json.dumps({"error": "invalid-input"}))
        sys.stdout.write("\n")
        raise SystemExit(2)
    rep = replay(n, cap, edges, rounds)
    out = build_output(n, edges, rounds, rep)
    sys.stdout.write(json.dumps(out))
    sys.stdout.write("\n")
    raise SystemExit(0)


if __name__ == "__main__":
    main()
