        E=len(self.edges); self.E=E
        self.U=[e["u"] for e in self.edges]; self.V=[e["v"] for e in self.edges]
        self.P=[e["ping_us"] for e in self.edges]; self.A=[e["ack_us"] for e in self.edges]
        self.L=[e["label"] for e in self.edges]
        self.out=[[] for _ in range(self.n)]
        for i in range(E): self.out[self.U[i]].append(i)
        R=len(self.rounds); self.R=R
        self.launch=[r["launch_us"] for r in self.rounds]
        self.deadline=[r["launch_us"]+r["timeout_us"] for r in self.rounds]
        self.hdel=[r["host_delay_us"] for r in self.rounds]
        self.dropH=[r["drop_host_ack"] for r in self.rounds]
        self.dropP=[set(r["drop_ping"]) for r in self.rounds]
        self.dropA=[set(r["drop_ack"]) for r in self.rounds]
        self.evs=[]; self.order=0
        self.ent={}; self.ncount=[0]*self.n; self.cpeak=[0]*self.n
        self.tot=0; self.peak=0
